def evaluate_tsp_config(cfg: CandidateConfig, seeds: list[int]) -> dict[str, float]:
    gaps: list[tuple[str, str, float]] = []
    for inst in TSP_INSTANCES:
        for version in NEIGHBOURHOOD_VERSIONS:
            for seed in seeds:
                tsp = SymmetricTSP(seed, inst.path, version)
                tracked = TrackedProblem(tsp, cfg.ns, cfg.max_evaluations)
                try:
                    BeesAlgorithmSolver(tracked, cfg).run()
                except BudgetExhausted:
                    pass
                gap = (
                    100.0
                    * (tracked.tracker.best_solution.fitness - inst.optimum)
                    / inst.optimum
                )
                gaps.append((inst.name, version, gap))

    return {
        "mean_gap": statistics.mean(g for _, _, g in gaps),
        "reverse_gap": statistics.mean(g for _, v, g in gaps if v == "REVERSE"),
        "swap_gap": statistics.mean(g for _, v, g in gaps if v == "SWAP"),
        "berlin52_reverse_gap": statistics.mean(
            g for i, v, g in gaps if i == "berlin52" and v == "REVERSE"
        ),
        "ch150_reverse_gap": statistics.mean(
            g for i, v, g in gaps if i == "ch150" and v == "REVERSE"
        ),
    }


def evaluate_continuous_config(
    cfg: CandidateConfig, seeds: list[int]
) -> tuple[float, dict[tuple[str, int], float]]:
    results: dict[tuple[str, int], float] = {}
    for func_cfg in BENCHMARK_FUNCTIONS:
        fn_name = func_cfg.function.__name__
        for dim in DIMENSIONS:
            vals: list[float] = []
            for seed in seeds:
                cfo = ContinuousFunctionOptimisation(
                    seed, func_cfg.lower, func_cfg.upper, dim, func_cfg.function
                )
                tracked = TrackedProblem(cfo, cfg.ns, cfg.max_evaluations)
                try:
                    BeesAlgorithmSolver(tracked, cfg).run()
                except BudgetExhausted:
                    pass
                vals.append(tracked.tracker.best_solution.fitness)
            results[(fn_name, dim)] = statistics.mean(vals)

    log_score = sum(math.log10(max(v, 1e-30)) for v in results.values()) / len(results)
    return log_score, results


def tune_tsp(seeds: list[int]) -> tuple[str, CandidateConfig, dict[str, float]]:
    print(f"=== Tuning TSP Configurations (seeds={seeds}) ===")
    best_entry: tuple[str, CandidateConfig, dict[str, float]] | None = None

    for label, cfg in TSP_CANDIDATES:
        metrics = evaluate_tsp_config(cfg, seeds)
        print(
            f"{label:48s} | all={metrics['mean_gap']:6.2f}% "
            f"| REV={metrics['reverse_gap']:5.2f}% SWAP={metrics['swap_gap']:6.2f}% "
            f"| b52_REV={metrics['berlin52_reverse_gap']:5.2f}% "
            f"ch150_REV={metrics['ch150_reverse_gap']:6.2f}%"
        )
        if best_entry is None or metrics["reverse_gap"] < best_entry[2]["reverse_gap"]:
            best_entry = (label, cfg, metrics)

    assert best_entry is not None
    print(f"\nBest TSP Config: {best_entry[0]} -> {best_entry[1]}\n")
    return best_entry


def tune_continuous(
    seeds: list[int],
) -> tuple[str, CandidateConfig, dict[tuple[str, int], float]]:
    print(f"=== Tuning Continuous Function Configurations (seeds={seeds}) ===")
    best_entry: (
        tuple[str, CandidateConfig, float, dict[tuple[str, int], float]] | None
    ) = None

    for label, cfg in CONTINUOUS_CANDIDATES:
        log_score, res = evaluate_continuous_config(cfg, seeds)
        print(
            f"{label:48s} | log10={log_score:6.2f} "
            f"| sph10={res[('sphere', 10)]:.1e} sph30={res[('sphere', 30)]:.1e} "
            f"| ros10={res[('rosenbrock', 10)]:5.2f} ros30={res[('rosenbrock', 30)]:5.1f} "
            f"| ras10={res[('rastrigin', 10)]:5.2f} ras30={res[('rastrigin', 30)]:5.1f} "
            f"| ack10={res[('ackley', 10)]:.2e} ack30={res[('ackley', 30)]:5.2f}"
        )
        if best_entry is None or log_score < best_entry[2]:
            best_entry = (label, cfg, log_score, res)

    assert best_entry is not None
    print(f"\nBest Continuous Config: {best_entry[0]} -> {best_entry[1]}\n")
    return best_entry[0], best_entry[1], best_entry[3]


def main() -> None:
    seeds = [SEED + i for i in range(EXPERIMENT_RUNS)]
    tune_tsp(seeds)
    tune_continuous(seeds)


if __name__ == "__main__":
    main()
